using System;
using System.IO;
using Microsoft.Win32;
namespace CalendarWeather;
public static class StartupService {
 public static string LinkPath=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Startup),"Windows Calendar e Weather Widget.lnk");
 internal static bool Matches(string target,string arguments,string expected){try{return string.Equals(Path.GetFullPath(target),Path.GetFullPath(expected),StringComparison.OrdinalIgnoreCase)&&arguments.Trim()=="--startup";}catch{return false;}}
 public static async System.Threading.Tasks.Task<bool> EnabledAsync()=>Distribution.IsPackaged?await Distribution.StartupEnabled():Enabled();
 public static bool Enabled(){if(File.Exists(LinkPath)){try{var type=Type.GetTypeFromProgID("WScript.Shell");if(type==null)return false;dynamic shell=Activator.CreateInstance(type)!;try{dynamic shortcut=shell.CreateShortcut(LinkPath);try{return Matches((string)shortcut.TargetPath,(string)shortcut.Arguments,Environment.ProcessPath!);}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shortcut);}}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}catch{return false;}}try{using var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run");return key?.GetValue("WindowsCalendarWeatherWidget") is string value&&value.Trim()=="\""+Environment.ProcessPath+"\" --startup";}catch{return false;}}
 public static async System.Threading.Tasks.Task Set(bool enable){if(Distribution.IsPackaged){await Distribution.SetStartup(enable);return;}if(enable){var type=Type.GetTypeFromProgID("WScript.Shell")??throw new InvalidOperationException("Atalhos do Windows indisponíveis.");dynamic shell=Activator.CreateInstance(type)!;try{Directory.CreateDirectory(Path.GetDirectoryName(LinkPath)!);dynamic shortcut=shell.CreateShortcut(LinkPath);try{shortcut.TargetPath=Environment.ProcessPath;shortcut.Arguments="--startup";shortcut.WorkingDirectory=AppContext.BaseDirectory;shortcut.Description="Windows Calendar e Weather Widget";shortcut.IconLocation=Path.Combine(AppContext.BaseDirectory,"Assets","Calendar-Fluent.ico");shortcut.Save();}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shortcut);}}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}if(!File.Exists(LinkPath))throw new IOException("O atalho de inicialização não foi salvo.");}else{if(File.Exists(LinkPath))File.Delete(LinkPath);try{using var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run",true);key?.DeleteValue("WindowsCalendarWeatherWidget",false);}catch{throw new InvalidOperationException("Não foi possível verificar a desativação no Registro. Confira Aplicativos de inicialização do Windows.");}}}
}
